import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Search, ShoppingBag, Filter } from 'lucide-react';
import { useProducts } from '../../hooks/useProducts';
import ProductCard from './ProductCard';

const CATEGORIES = ["Tümü", "Performans", "Ekipman", "Bakım", "Aksesuar"];

import { ProductCategory } from '../../types';

export const MobileShop = ({ onNavigate, initialCategory = 'ALL', cartCount = 0 }: { onNavigate: (view: any, data?: any) => void, initialCategory?: ProductCategory | 'ALL', cartCount?: number }) => {
    const { data: products, isLoading } = useProducts();
    const [searchQuery, setSearchQuery] = useState("");
    const [activeCategory, setActiveCategory] = useState<string>(initialCategory === 'ALL' ? "Tümü" : initialCategory);

    const filteredProducts = products?.filter((product) => {
        const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesCategory = activeCategory === "Tümü" || product.category === activeCategory;
        return matchesSearch && matchesCategory;
    }) || [];

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-black pb-24 text-zinc-900 dark:text-white transition-colors duration-300">
            {/* Header */}
            <div className="sticky top-0 z-20 bg-white/80 dark:bg-black/80 backdrop-blur-xl border-b border-gray-200 dark:border-white/5 px-4 pt-12 pb-4">
                <div className="flex items-center justify-between mb-4">
                    <h1 className="text-2xl font-bold tracking-tighter italic">MOTO<span className="text-[#E2FF3B]">MAĞAZA</span></h1>
                    <button onClick={() => onNavigate('cart')} className="relative p-2 -mr-2">
                        <ShoppingBag className="text-zinc-800 dark:text-white" size={24} />
                        {cartCount > 0 && (
                            <span className="absolute top-1 right-0 flex h-4 w-4 items-center justify-center rounded-full bg-[#E2FF3B] text-[10px] font-bold text-black">
                                {cartCount}
                            </span>
                        )}
                    </button>
                </div>

                {/* Search Bar */}
                <div className="relative mb-4">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-500" size={18} />
                    <input
                        type="text"
                        placeholder="Parça veya SKU ara..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full bg-gray-100 dark:bg-zinc-900 border border-gray-200 dark:border-zinc-800 rounded-xl py-3 pl-10 pr-4 text-sm text-zinc-900 dark:text-white focus:outline-none focus:border-[#E2FF3B]/50 transition-colors placeholder:text-zinc-500 dark:placeholder:text-zinc-600"
                    />
                </div>

                {/* Categories */}
                <div className="flex gap-2 overflow-x-auto scrollbar-hide -mx-4 px-4">
                    {CATEGORIES.map((cat) => (
                        <button
                            key={cat}
                            onClick={() => setActiveCategory(cat)}
                            className={`px-4 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all ${activeCategory === cat
                                ? 'bg-[#E2FF3B] text-black shadow-[0_0_15px_-5px_rgba(226,255,59,0.5)]'
                                : 'bg-gray-200 dark:bg-zinc-900 text-zinc-600 dark:text-zinc-500 border border-gray-300 dark:border-zinc-800'
                                }`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>
            </div>

            {/* Product Grid */}
            <div className="p-4">
                {isLoading ? (
                    <div className="flex justify-center py-20">
                        <div className="w-8 h-8 border-2 border-[#E2FF3B] border-t-transparent rounded-full animate-spin" />
                    </div>
                ) : (
                    <div className="grid grid-cols-2 gap-4">
                        {filteredProducts.map((product) => (
                            <ProductCard
                                key={product._id}
                                product={product}
                                onClick={() => onNavigate('product-detail', product)}
                            />
                        ))}
                    </div>
                )}

                {!isLoading && filteredProducts.length === 0 && (
                    <div className="text-center py-20 text-zinc-500">
                        <p>Ürün bulunamadı.</p>
                    </div>
                )}
            </div>
        </div>
    );
};


